// Athlete race-photo lookup keyed by bib.
//
// Reads data/athlete-photos.json (generated by scripts/build-athlete-photos.mjs)
// and returns a Drive thumbnail URL for the given bib. Everything is keyed on
// bib so the photo can show up even for athletes who didn't fill in the
// pre-event survey. If the manifest is missing or the bib isn't in it, returns
// null and the caller renders nothing.

let loadPromise = null;

function load() {
  if (!loadPromise) {
    loadPromise = (async () => {
      try {
        const res = await fetch(new URL("../data/athlete-photos.json", import.meta.url));
        if (!res.ok) return {};
        const data = await res.json();
        return data.photos || {};
      } catch {
        return {};
      }
    })();
  }
  return loadPromise;
}

export async function photoSrcForBib(bib, sizeW = 400) {
  if (bib == null || bib === "") return null;
  const map = await load();
  const id = map[String(bib)];
  if (!id) return null;
  return `https://drive.google.com/thumbnail?id=${id}&sz=w${sizeW}`;
}
